fixed_example.code:
@router.get("/dossiers/{dossier_id}")
async def lire(dossier_id: str, user: User = Depends(current_user)):
    dossier = await Dossier.get(id=dossier_id, org_id=user.org_id)
    if dossier is None:
        raise HTTPException(404)     # 404, pas 403 : ne pas confirmer l'existence
    return dossier
